PRAGMA auto_vacuum=FULL; CREATE TABLE t1(x UNIQUE); CREATE TABLE t2(y UNIQUE); CREATE TABLE t3(z UNIQUE); WITH RECURSIVE c(i) AS (VALUES(1) UNION ALL SELECT i+1 FROM c WHERE i<16) INSERT INTO t1 SELECT printf('%0*d',CASE WHEN i<=2 THEN 202 WHEN i<=4 THEN 203 WHEN i<=8 THEN 204 ELSE 205 END,i) FROM c; INSERT INTO t2 VALUES(printf('%0*d',203,900)); INSERT INTO t2 SELECT printf('%0*d',length(x),1000+rowid) FROM t1; INSERT INTO t3 VALUES(printf('%0*d',204,900)); INSERT INTO t3 SELECT printf('%0*d',length(x),2000+rowid) FROM t1;